ROOT = Path(__file__).resolve().parents[1]
E = html.escape
RESOURCES = json.loads((ROOT/'content/resources.json').read_text(encoding='utf-8'))


def opening(kicker, title, text, links=''):
    return f'<section class="depth-hero"><div class="container"><div class="eyebrow">{kicker}</div><h1>{title}</h1><p>{text}</p>{"<div class=depth-actions>"+links+"</div>" if links else ""}</div></section>'


def cards(items, cls='depth-cards'):
    return f'<div class="{cls}">'+''.join(f'<article><span class="depth-number">{i:02}</span><h3>{title}</h3><p>{text}</p></article>' for i,(title,text) in enumerate(items,1))+'</div>'


def close(title='Bring us the question<br>that matters to you.', url='briefing.html'):
    return f'<section class="depth-close container"><div class="eyebrow">A conversation with context</div><h2>{title}</h2><p>Tell us which decision the research needs to inform and what evidence is missing.</p><a class="button button-coral" href="{url}">See how we can help you </a></section>'


def product_map():
    return '''<div class="workflow-canvas"><div class="workbench-bar"><span><i></i> ECHOFRAME / RESEARCH WORKFLOW</span><span>ILLUSTRATIVE PRODUCT DESIGN</span></div><div class="workflow-columns"><div class="workflow-sources"><span class="eyebrow">01 / Collect & preserve</span><a href="sources.html#ofac">Official records <small>Authority · Document · Date</small></a><a href="evidence-workspace.html">Local reporting <small>Claim · Place · Provenance</small></a><a href="evidence-workspace.html">Physical observations <small>Coverage · Precision · Limits</small></a></div><div class="workflow-middle"><span class="eyebrow">02 / Connect & challenge</span><a href="evidence-workspace.html"><strong>The event record</strong><small>Accounts of the same event.</small></a><a href="actor-mapping.html"><strong>The actor & asset context</strong><small>Roles, relationships, and dependencies.</small></a></div><div class="workflow-question"><span class="eyebrow">03 / Assess & explain</span><h3>One clear question.<br>The evidence behind it.</h3><p>What has changed? Why does it matter? What should you watch next?</p><a href="sample-briefs.html">Research brief formats </a></div></div><p class="visual-caption">Connections show a proposed analytical workflow, not data volumes or live integrations. This public illustration does not establish the deployment or update cadence of a client service.</p></div>'''


def capabilities():
    result=opening('The EchoFrame research system','Judgment you can<br>defend to a board','A structured assessment examines where the country is heading, what could change and whether an opportunity meets your requirements. Follow each judgment back to the evidence that supports it.','<a class="button" href="sample-briefs.html">Explore sample briefs </a><a class="text-link" href="#capability-modules">Inside the capabilities </a>')
    result+='<section class="container product-overview">'+product_map()+'</section>'
    result+='''<section class="section container" id="capability-modules"><div class="section-heading"><div><div class="eyebrow">Three connected research capabilities</div><h2>Follow the story.<br>Test what it means.</h2></div><p>Start with the people involved, examine the evidence, then ask what could change the outlook.</p></div><div class="capability-grid">'''
    for code,title,desc,url,tags in [
        ('01','Actor & asset mapping','Understand who can influence a decision and which operational dependencies surround the asset.','actor-mapping.html',['Documented roles','Relationship evidence','Asset dependencies']),
        ('02','Evidence workspace','Keep claims, contradictions, timing, and source independence visible in one research record.','evidence-workspace.html',['Source ledger','Event review','Contradiction handling']),
        ('03','Decision pathways','Identify observable milestones, alternative explanations, and the evidence that would justify a review.','decision-pathways.html',['Bounded questions','Review triggers','Resolution rules'])]:
        result+=f'<article><a class="module-art module-{code}" href="{url}" aria-label="Explore {title}"><span>{code}</span><div aria-hidden="true"><i></i><i></i><i></i></div><b></b></a><h3><a href="{url}">{title}</a></h3><p>{desc}</p><ul>'+''.join(f'<li>{t}</li>' for t in tags)+f'</ul><a class="text-link" href="{url}">Explore the capability </a></article>'
    result+='</div></section><section class="depth-wash"><div class="container split-depth"><div><div class="eyebrow">Built around a research mandate</div><h2>From the first question<br>to the finished brief.</h2><p>Good research starts with a clear question. It gathers the evidence, weighs competing explanations, and gives the reader a judgment they can examine.</p></div><ol class="delivery-steps"><li><strong>Frame</strong><p>Name the asset or counterparty, the decision horizon, and the outcome that would matter.</p></li><li><strong>Investigate</strong><p>Build a source plan, register competing claims, and check the quality of the available evidence.</p></li><li><strong>Review</strong><p>Challenge the interpretation, document missing evidence, and separate operational questions from legal or valuation work.</p></li><li><strong>Brief</strong><p>Present an assessment, supporting records, alternatives, and an explicit review trigger.</p></li></ol></div></section>'
    result+=risk_dimensions()+scenario_framework()
    result+='<section class="section container"><div class="eyebrow">Read the result in context</div><h2>Every number needs an explanation</h2><p class="depth-lead">An assessment should show its date, the evidence behind a movement, the alternatives considered, and the next review trigger. This public walkthrough explains the framework. It does not present a live risk feed or client-specific probabilities.</p><a class="text-link" href="decision-pathways.html#entry-tests">Explore the six decision tests </a></section>'
    return result+close()


def actor_mapping():
    return '<section class="depth-hero"><div class="container"><div class="eyebrow">Capability 01 / Actor &amp; asset mapping</div><h1>Who has the power<br/>to change the outcome?</h1><p>An organisation chart identifies formal positions. A stakeholder assessment examines who makes a decision, who carries it out and who is affected. Each relationship needs evidence of the role it describes, together with its date and any uncertainty.</p></div></section><section class="section container"><div class="section-heading"><div><div class="eyebrow">Every connection needs a source</div><h2>Relationships need evidence.</h2></div></div><div class="depth-cards"><article><span class="depth-number">01</span><h3>Distinguish authority from influence</h3><p>A statutory role, public advocacy, ownership interest, and reported informal influence describe different relationships. Record the type before drawing the line.</p></article><article><span class="depth-number">02</span><h3>Anchor the claim in time</h3><p>A board appointment or local position can change. Keep the source date, validity period, and review trigger with the relationship.</p></article><article><span class="depth-number">03</span><h3>Preserve what is unknown</h3><p>An unresolved relationship should remain unresolved. Visual proximity is not a substitute for proof of control, coordination, or access.</p></article></div></section><section class="depth-wash"><div class="container split-depth"><div><div class="eyebrow">The resulting brief</div><h2>Know who matters.<br/>Know what to ask.</h2><p>A map is the index to the reasoning. The accompanying note explains why a relationship matters and what remains uncertain.</p><a class="button" href="sample-asset-access.html">Asset brief structure </a></div><div class="deliverable-sheet"><div class="sheet-label">PROPOSED BRIEF CONTENTS</div><ol><li>Decision and institutional pathway</li><li>Actor register with documented roles</li><li>Relationship ledger and source references</li><li>Asset and operating dependencies</li><li>Unresolved claims and alternative explanations</li><li>Questions for engagement and review horizon</li></ol></div></div></section><section class="section container"><h2>Useful when the decision depends on people.</h2><p class="depth-lead">For government affairs teams, the map can focus the next stakeholder conversation. For investment teams, it can help test assumptions about counterparties, authority, and implementation. It does not turn reported relationships into legal findings or imply access to the people represented.</p><div class="depth-related"><a href="government-affairs.html">Government affairs use cases </a><a href="distressed-debt.html">Distressed-debt use cases </a><a href="sources.html">Explore the source directory </a></div></section><section class="depth-close container"><div class="eyebrow">A conversation with context</div><h2>Bring us the question<br/>that matters to you.</h2><p>Tell us which decision the research needs to inform and what evidence is missing.</p><a class="button button-coral" href="briefing.html">See how we can help you </a></section>'


EVIDENCE = [
    ('E-01','Official','Day 1, 09:00','The terminal remains open.','Contradicted','An operator statement about general operations. It does not isolate contractor access.'),
    ('E-02','Local','Day 1, 11:30','Contractor entry was interrupted.','Contradicted','A fictional local account refers to a specific gate and a narrower activity.'),
    ('E-03','Media','Day 1, 13:00','The terminal remains open.','Repeated','This fictional item repeats E-01 and adds no independent observation.'),
    ('E-04','Physical','Day 2, 08:00','Activity is visible in the wider terminal area.','Limited','The illustrative observation cannot establish who entered or whether every operation continued.'),
]


def evidence_table():
    return '<div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable research table"><table class="depth-table evidence-ledger"><caption>Fictional source ledger · No live reporting or real source identities</caption><thead><tr><th scope="col">Record / channel</th><th scope="col">Observed claim</th><th scope="col">Review state</th><th scope="col">Interpretation limit</th></tr></thead><tbody>'+''.join(f'<tr data-ledger-state="{state.lower()}"><th scope="row">{code}<small>{channel} · {time}</small></th><td>{claim}</td><td><span class="evidence-pill state-{state.lower()}">{state}</span></td><td>{limit}</td></tr>' for code,channel,time,claim,state,limit in EVIDENCE)+'</tbody></table></div>'


def evidence_workspace():
    return '<section class="depth-hero"><div class="container"><div class="eyebrow">Capability 02 / Evidence workspace</div><h1>When accounts differ,<br/>follow the evidence.</h1><p>Each source needs to be read for what it establishes. Compare the activity, location and observation period before deciding whether accounts agree or conflict. Keep the original source and the reason for your assessment together.</p></div></section><section class="depth-wash"><div class="container"><div class="section-heading"><div><div class="eyebrow">A record you can inspect</div><h2>What travels with the evidence.</h2></div></div><div class="depth-cards"><article><span class="depth-number">01</span><h3>Provenance</h3><p>Source reference, publisher, underlying reporting origin, publication time, collection time, and permitted use.</p></article><article><span class="depth-number">02</span><h3>Scope</h3><p>Event time, place precision, named actors, activity described, and the part of the claim actually observed.</p></article><article><span class="depth-number">03</span><h3>Review history</h3><p>Grouping rationale, independence check, contradictions, analyst interpretation, and the next review trigger.</p></article></div></div></section><section class="section container"><h2>Build the source register before the score.</h2><p class="depth-lead">The connected event and corroboration workflow remains in development. A useful research record preserves the source, its limits and the review history. The fields below describe the information needed for that record.</p><div class="depth-related"><a download="" href="downloads/evidence-register.csv">Download a blank evidence register </a><a href="trust.html">Source handling and publication rules </a><a href="research/when-sources-disagree.html">Read the evidence guide </a></div></section><section class="depth-close container"><div class="eyebrow">A conversation with context</div><h2>Bring us the question<br/>that matters to you.</h2><p>Tell us which decision the research needs to inform and what evidence is missing.</p><a class="button button-coral" href="briefing.html">See how we can help you </a></section>'


def pathways():
    return '<section class="depth-hero"><div class="container"><div class="eyebrow">Capability 03 / Decision pathways</div><h1>Know what would<br/>change your assessment.</h1><p>An assessment becomes easier to review when the question names an outcome, a deadline and the evidence needed to establish it. Record the observation that would change your view and explain why it matters to the decision.</p></div></section>' + entry_tests() + '<section class="section container"><div class="section-heading"><div><div class="eyebrow">Make the question resolvable</div><h2>A better question<br/>than “How risky is the country?”</h2></div></div><div class="depth-cards"><article><span class="depth-number">01</span><h3>Define the outcome</h3><p>Specify the subject, activity, observation period, and source rule. Avoid questions that can only be answered with another subjective adjective.</p></article><article><span class="depth-number">02</span><h3>Separate evidence from likelihood</h3><p>Confidence in a source and probability of a future event are different judgments. Each needs its own basis and limitations.</p></article><article><span class="depth-number">03</span><h3>Keep an update history</h3><p>Explain why an observation supports a change, why an alternative survives, or why the available record remains insufficient.</p></article></div></section><section class="depth-wash"><div class="container split-depth"><div><div class="eyebrow">For distressed-debt research</div><h2>Test the assumptions<br/>behind the investment.</h2><p>Start with the part of the investment case that depends on politics or operations. Name the decision that must happen, the party responsible, and the evidence that would make you reconsider.</p><a class="button" href="sample-thesis-review.html">Investment brief structure </a></div><div class="deliverable-sheet"><div class="sheet-label">QUESTION REGISTER / SUGGESTED FIELDS</div><ol><li>Question and decision owner</li><li>Outcome and resolution deadline</li><li>Initial reasoning and alternatives</li><li>Evidence that would support or challenge</li><li>Review history and unresolved gaps</li><li>Resolution and subsequent learning</li></ol></div></div></section><section class="section container"><h2>Validation belongs in the workflow.</h2><p class="depth-lead">A numerical forecast needs a documented basis, timestamped updates, resolution criteria, and evaluation against observed outcomes. Review the complete record and its benchmark, including unsuccessful calls. A selected historical case is not a substitute for that evaluation.</p><div class="depth-related"><a download="" href="downloads/question-register.csv">Download a question register </a><a href="methodology.html">Explore the full methodology </a></div></section><section class="depth-close container"><div class="eyebrow">A conversation with context</div><h2>Bring us the question<br/>that matters to you.</h2><p>Tell us which decision the research needs to inform and what evidence is missing.</p><a class="button button-coral" href="briefing.html">See how we can help you </a></section>'


def sources():
    result=opening('Research resources / Primary sources','Go to the source.<br>Read it in context.','These sources provide official records relevant to the research. Each entry explains where to find the material, what to look for and the limits of what it establishes.')
    result+='''<section class="container section"><div class="source-controls"><label>Find a source<input id="source-search" type="search" placeholder="Try sanctions, filings, or energy"></label><label>Research area<select id="source-category"><option>All sources</option><option>Policy &amp; law</option><option>Energy &amp; assets</option><option>Disputes &amp; counterparties</option></select></label></div><div class="source-library-meta"><span id="source-count" role="status">6 sources</span><span>DIRECTORY REVIEWED 11 SEPTEMBER 2026 · SOURCE VINTAGES VARY</span></div><div class="source-grid">'''
    for r in RESOURCES:
        result+=f'<article class="source-card" id="{r["id"]}" data-source-category="{E(r["category"])}" data-source-search="{E((r["name"]+" "+r["description"]+" "+r["use"]).lower())}"><div class="eyebrow">{E(r["category"])}</div><h2><a href="{r["url"]}" target="_blank" rel="noopener noreferrer">{E(r["name"])} </a></h2><span class="source-publisher">{E(r["publisher"])}</span><p>{E(r["description"])}</p><dl><dt>How to use it</dt><dd>{E(r["use"])}</dd><dt>Read with this limitation</dt><dd>{E(r["limit"])}</dd></dl><a class="text-link" href="{r["url"]}" target="_blank" rel="noopener noreferrer">Open the primary source </a></article>'
    result+='''</div><div id="source-empty" class="empty-state" hidden><h2>No sources match.</h2><p>Try a broader term or choose all research areas.</p><button id="source-reset" class="button">Reset source filters</button></div><p class="visual-caption">These are external research references, not data partnerships or integrations. Directory review does not mean every document is current. Check the date and version of the underlying material before using it.</p></section><section class="depth-wash"><div class="container split-depth"><div><div class="eyebrow">Venezuela context notebook</div><h2>Separate structural context<br>from current conditions.</h2><p>Explore a short sourced notebook on reserves, operating constraints, and the documents needed for an asset-level question.</p><a class="button" href="venezuela-context.html">Open the context notebook </a></div><div><h3>Build a repeatable source record.</h3><p>Use the blank register to record the source, date, claim, precision, independence check, and publication permissions for each item.</p><a class="text-link" href="downloads/evidence-register.csv" download>Download the evidence register </a></div></div></section>'''
    return result


def context_notebook():
    return opening('Venezuela / Sourced context notebook','Large reserves.<br>Specific operating questions.','Structural background for an asset-level research mandate. The figures below describe historical observation periods; they are not a current market or facility-status update.')+'''<section class="section container"><div class="context-facts"><article><span class="eyebrow">EIA / 2023 reserves</span><strong>303bn</strong><p>Approximately 303 billion barrels of proved crude oil reserves.</p></article><article><span class="eyebrow">EIA / 2023 production share</span><strong>0.8%</strong><p>Venezuela's share of global crude oil production in that year.</p></article><article><span class="eyebrow">EIA / Resource composition</span><strong>Extra-heavy</strong><p>Most proved reserves are extra-heavy crude in the Orinoco Belt.</p></article></div><p class="source-citation">Historical figures and resource description: <a href="https://www.eia.gov/international/content/analysis/countries_long/Venezuela/" target="_blank" rel="noopener noreferrer">EIA, Venezuela country analysis </a>. Accessed 11 September 2026; figures refer to 2023.</p><div class="context-essay"><h2>What the gap asks of the research.</h2><p>This historical contrast points to a research need. A large resource base does not establish present operating access, deliverability or a particular commercial position. The analyst needs a narrower unit of analysis and a more recent evidence record.</p><p>For a government affairs team, that unit might be an approval pathway around a terminal or project. For a distressed-debt team, it might be the political and operational assumptions attached to a counterparty. These questions call for different documents even when they share the same country context.</p><h2>Build three separate evidence files.</h2><div class="notebook-sections"><article><span>01</span><div><h3>The authority file</h3><p>Record the instrument, named parties, relevant activity, effective date, and review horizon. OFAC's programme page is a starting point for U.S. sanctions documents and guidance; the transaction-specific conclusion needs specialist review.</p><a href="https://ofac.treasury.gov/sanctions-programs-and-country-information/venezuela-related-sanctions" target="_blank" rel="noopener noreferrer">Primary reference: OFAC Venezuela programme </a></div></article><article><span>02</span><div><h3>The operating file</h3><p>Define the asset, access route, service dependency, and observation period. Compare public statements with independently sourced local or physical observations. A national production series cannot resolve a gate-level access question.</p><a href="sample-asset-access.html">Asset research brief structure </a></div></article><article><span>03</span><div><h3>The counterparty file</h3><p>Keep issuer disclosures and procedural records separate from assertions about recovery. EDGAR and ICSID provide useful starting points for filings and registered cases, with their respective coverage and disclosure limits.</p><a href="sources.html?category=Disputes%20%26%20counterparties">Explore counterparty research sources </a></div></article></div><h2>Make the date part of the claim.</h2><p>A source can be authoritative and still describe an earlier period. Store the publication date, observation period, access date, and any known expiry or supersession information separately. Re-open time-sensitive source material at the point of use.</p><p>This notebook combines cited historical background with EchoFrame's original research framework. It contains no current production estimate, legal clearance, issuer valuation, or trade recommendation.</p></div></section>'''+close('Take the country context<br>down to the asset.')


def trust():
    return opening('Trust / Evidence, access & privacy','Trust begins with<br>showing the work.','Before private research begins, we agree how the material will be used, who can receive it and how sensitive information will be handled.') + '<section class="section container"><div class="section-heading"><div><div class="eyebrow">Before a private engagement</div><h2>Agree the handling<br>before sharing the material.</h2></div><p>These requirements form part of the discussion before work begins. They need to reflect the sources, intended recipients and sensitivity of the particular engagement.</p></div>' + cards([
        ('Access and permitted use','Agree who can access the output, whether redistribution is allowed, and which source licences constrain publication.'),
        ('Sensitive material','Agree a suitable exchange channel and source-protection arrangements before sending confidential or identifying information.'),
        ('Retention and deletion','Document the retention period, storage arrangements, responsibilities, and process for correction or deletion requests.')]) + '<p>The agreed scope should identify the material covered by these arrangements and who is responsible for applying them. Resolve questions about access and permitted use before sensitive material is shared.</p></section><section class="depth-wash"><div class="container split-depth"><div><h2>What happens<br>to your information.</h2><p>The <a href="privacy.html">privacy notice</a> explains how this website handles enquiries, saved reading lists and service records.</p></div><div><h2>Show uncertainty.<br>Make corrections possible.</h2><p>The <a href="editorial-standards.html">editorial standards</a> explain attribution, uncertainty, source protection and corrections.</p></div></div></section>'


def engagement():
    return opening('Working with EchoFrame','Start with the decision.<br>Agree the work it needs.','Tell us the decision you face and the time you have. We can then discuss the research, sources, and format that would help. Scope, timing, and fees are agreed before work begins.')+'''<section class="section container"><div class="engagement-grid">'''+''.join(f'<article><div class="eyebrow">{kicker}</div><h2>{title}</h2><p>{desc}</p><dl><dt>Useful for</dt><dd>{fit}</dd><dt>Possible output</dt><dd>{output}</dd></dl><a class="button" href="briefing.html?format={code}">Discuss this format </a></article>' for kicker,title,desc,fit,output,code in [
        ('01 / Frame the problem','Scoping conversation','An introductory discussion to define the subject, decision horizon, and evidence needed.','A new regional question or an unclear research requirement.','An agreed next step and the boundaries of a potential mandate.','Scoping conversation'),
        ('02 / Investigate a question','Focused research brief','A bounded investigation around a policy, actor, counterparty, or asset question.','A stakeholder meeting, internal decision, or thesis-review milestone.','An evidence-linked brief, unresolved questions, and a review horizon.','Focused research brief'),
        ('03 / Follow the change','Recurring research review','A proposed cadence for revisiting a defined question as relevant evidence changes.','A continuing policy process or a thesis with observable milestones.','A change log, revised assessment, and agreed escalation criteria.','Recurring research review')])+'''</div></section><section class="depth-wash"><div class="container split-depth"><div><div class="eyebrow">From introduction to output</div><h2>Build agreement<br>at each stage.</h2><p>A useful brief starts with a shared definition of what the work can answer. Scope should reflect source availability and the time you have.</p></div><ol class="delivery-steps"><li><strong>Define the decision</strong><p>Identify the research user, the subject, and the consequence of getting the question wrong.</p></li><li><strong>Agree the mandate</strong><p>Confirm geography, sources, exclusions, delivery date, format, use rights, and commercial terms.</p></li><li><strong>Review the evidence</strong><p>Assess the source record, challenge the interpretation, and record any gaps affecting the answer.</p></li><li><strong>Deliver and discuss</strong><p>Explain the conclusion, alternatives, limitations, and observations that would trigger another review.</p></li></ol></div></section><section class="section container"><div class="section-heading"><div><div class="eyebrow">Prepare for the first conversation</div><h2>Bring four things.</h2></div></div>'''+cards([
        ('The subject','An asset, contract, counterparty, institution, or place at the right level of specificity.'),
        ('The decision','The action or internal discussion that the research is intended to inform.'),
        ('The horizon','The deadline and the policy, operational, or procedural milestone that creates it.'),
        ('The gap','What you already know, which assumption is unresolved, and the evidence that would help.')], 'depth-cards trust-cards')+'''<div class="depth-related"><a href="downloads/research-mandate.md" download>Download a mandate template </a><a href="sample-briefs.html">Research templates and brief structure </a><a href="trust.html">Review information-handling boundaries </a></div></section>'''+close()


def audience_depth(key):
    return {'government': '<section class="section container audience-depth"><div class="section-heading"><div><div class="eyebrow">Recognise the research problem</div><h2>The next stakeholder meeting.</h2></div></div><div class="depth-cards"><article><span class="depth-number">01</span><h3>The national story misses the asset</h3><p>A country briefing does not tell you which local authority or operating dependency matters to the next decision.</p></article><article><span class="depth-number">02</span><h3>Stakeholder notes are scattered</h3><p>Names, appointments, and public positions sit in separate files without a dated relationship record.</p></article><article><span class="depth-number">03</span><h3>The meeting is approaching</h3><p>The team needs a defensible set of questions, the supporting evidence, and a clear account of what remains unresolved.</p></article></div></section><section class="depth-wash"><div class="container"><div><div class="eyebrow">Where the approach fits</div><h2>Get more from<br/>a defined mandate.</h2><ul class="fit-list"><li>Your mandate spans national policy and a local operating footprint.</li><li>You need to distinguish formal authority from reported influence.</li><li>Your team prepares stakeholder meetings or internal policy briefings.</li><li>You can define an asset, project, approval process, or access question.</li><li>You value a source-linked record and explicit uncertainty.</li></ul></div></div></section><section class="section container"><div class="section-heading"><div><div class="eyebrow">Explore the work in more detail</div><h2>See the method.<br/>Inspect the output.</h2></div></div><div class="depth-link-grid"><a href="actor-mapping.html"><span>01 / Capability</span><h3>Actor &amp; asset mapping</h3><p>Read how relationships are documented and checked.</p><b></b></a><a href="evidence-workspace.html"><span>02 / Capability</span><h3>Evidence workspace</h3><p>Follow conflicting claims through an inspectable source ledger.</p><b></b></a><a href="engagement.html"><span>03 / Working together</span><h3>Research formats</h3><p>Explore the scoping, delivery, and review process.</p><b></b></a></div></section>', 'credit': '<section class="section container audience-depth"><div class="section-heading"><div><div class="eyebrow">Recognise the research problem</div><h2>The next investment committee.</h2></div></div><div class="depth-cards"><article><span class="depth-number">01</span><h3>The political catalyst is too broad</h3><p>A thesis refers to political normalisation without specifying the decision, actor, or observable milestone.</p></article><article><span class="depth-number">02</span><h3>Documents and narratives diverge</h3><p>Company disclosures, procedural records, and public statements point to different parts of the story.</p></article><article><span class="depth-number">03</span><h3>The committee needs a review rule</h3><p>The team needs to know which new evidence would support, challenge, or leave the assumption unresolved.</p></article></div></section><section class="depth-wash"><div class="container"><div><div class="eyebrow">Where the approach fits</div><h2>Get more from<br/>a defined mandate.</h2><ul class="fit-list"><li>Your thesis depends on a political or operational assumption.</li><li>You research distressed debt, special situations, or complex counterparties.</li><li>You need to distinguish procedural developments from recovery assumptions.</li><li>You can name an issuer, asset, counterparty, and decision horizon.</li><li>You want research that complements legal and valuation specialists.</li></ul></div></div></section><section class="section container"><div class="section-heading"><div><div class="eyebrow">Explore the work in more detail</div><h2>See the method.<br/>Inspect the output.</h2></div></div><div class="depth-link-grid"><a href="actor-mapping.html"><span>01 / Capability</span><h3>Actor &amp; asset mapping</h3><p>Read how relationships are documented and checked.</p><b></b></a><a href="evidence-workspace.html"><span>02 / Capability</span><h3>Evidence workspace</h3><p>Follow conflicting claims through an inspectable source ledger.</p><b></b></a><a href="engagement.html"><span>03 / Working together</span><h3>Research formats</h3><p>Explore the scoping, delivery, and review process.</p><b></b></a></div></section>'}[key]


