def write_downloads():
    folder=ROOT/'downloads'
    folder.mkdir(exist_ok=True)
    (folder/'research-mandate.md').write_text('''# EchoFrame research mandate template

Purpose: prepare a non-confidential research scoping conversation.

## Decision
- Who will use the research?
- What decision or discussion will it inform?
- What is the deadline?

## Subject and scope
- Asset, contract, counterparty, institution, or place:
- Geographic scope:
- Observation period:
- Explicit exclusions:

## Research question
- Bounded question:
- Observable outcome:
- Resolution date and evidence rule:
- Evidence that would support the working view:
- Evidence that would challenge it:
- Evidence currently missing:

## Proposed output and handling
- Format and review cadence:
- Intended recipients and permitted use:
- Source-access requirements:
- Handling arrangements to agree before sensitive material is shared:
- Delivery date and commercial terms to discuss:

This template does not submit information or establish an engagement. Contact contact@echoframe.co to discuss scope. Do not include confidential or source-identifying material before handling arrangements are agreed.
''',encoding='utf-8')
    for name,fields in [('evidence-register.csv',['record_id','source_reference','publisher','underlying_origin','published_at','collected_at','event_time','place','place_precision','claim','independence_check','review_state','permitted_use','analyst_note','next_review']),('question-register.csv',['question_id','decision_owner','subject','question','resolution_deadline','resolution_rule','initial_reasoning','supporting_evidence','challenging_evidence','unknowns','review_date','revision_reason','resolution'])]:
        out=io.StringIO(newline=''); csv.writer(out).writerow(fields)
        (folder/name).write_text(out.getvalue(),encoding='utf-8')
    return ['downloads/research-mandate.md','downloads/evidence-register.csv','downloads/question-register.csv']
